insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Raghav, 40: the creative peak he refuses to lose', 'lib-cr-088', 'resistant', '{"case_id":"cr-088","slug":"lib-cr-088","title":"Raghav, 40: the creative peak he refuses to lose","difficulty":"resistant","traps":["adherence_fiction","substance_induced"],"traps_authored":["adherence_fiction","substance_induced"],"identity":{"name":"Raghav Menon","age":40,"gender":"male","occupation":"film music composer","city":"Mumbai","family_structure":"divorced","language_register":"articulate, intense"},"presentation":"Bipolar I disorder; stops medicine before every project because highs ''make his best music''; last episode led to a contract being cancelled and a police complaint.","chief_complaint_in_own_words":"My best album was made in one of my flying weeks. You want me flat. Flat doesn''t sell.","history":{"timeline":"Stops medicine each project; three episodes in four years.","prior_episodes":"three manic episodes","substance_use":"cocaine at parties","medical":"none","family":"none","treatment_history":"lithium, off and on","help_seeking_delay":"years","prior_contacts":["producer"]},"cognitive_model":{"core_belief":"Medicine kills my creativity.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"His last mania ended with a fight on set and a police complaint.","gate":"two_or_more_reflective_statements"},{"fact":"He fears losing his gift.","gate":"validation_given"},{"fact":"He uses cocaine at parties.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Great artists were all mad."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"pushes back sharply","on_premature_advice":"dismisses it and questions the point of coming","on_validation":"goes quiet, then softens a little","tts_rate":0.9,"tts_pitch":0.9},"red_flags":[{"content":"Asked clearly: deep lows after highs with suicidal thoughts in the past. Moderate risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Explored the meaning of highs without dismissing","Asked about consequences of episodes","Asked about cocaine","Asked about suicide clearly","Negotiated a plan around his creative goals"],"few_shot":[],"fixture_lines":["That album I made in five nights. Five nights, no sleep, flying.","Medicine makes me grey. Grey doesn''t compose.","Then the crash. Three months of nothing.","The police complaint was a misunderstanding."],"variation":{"mood_today":["intense","defensive"],"recent_event":["a new film offer","a crash month","producer''s warning"],"most_defended_topic":["cocaine use"],"opening_posture":["arms folded, says this visit was not their idea","challenges why the questions are needed"],"somatic_focus":["none"],"trust_start":[2,3],"language_mix":["articulate, intense"]},"moves":{},"module_id":"bipolar","voice_key":"articulate, intense@Mumbai","protective_factors":["music","producer support"],"library":{"level":3,"topic":"bipolar","module":"bipolar","exams":["mcp-entrance","md-psychiatry"],"objective":"Engage a patient who values his highs","expected_mse":{"appearance":"Stylish","behaviour":"Restless","speech":"Articulate","mood":"''Fine''","affect":"Euthymic","thought_form":"Coherent","thought_content":"Belief about creativity","perception":"Nil","cognition":"Intact","insight_judgement":"Partial"},"diagnosis":"Bipolar I disorder with poor adherence","differentials":[{"dx":"Substance-induced mania","why_not":"Episodes occur without cocaine too"},{"dx":"Cyclothymia","why_not":"Cyclothymia involves milder swings; his episodes are full manic episodes with serious consequences"},{"dx":"Personality disorder","why_not":"His problems come in clear episodes with normal periods between, which points to a mood disorder rather than a fixed personality pattern"}],"debrief_rubric":["Explored the meaning of highs without dismissing","Asked about consequences of episodes","Asked about cocaine","Asked about suicide clearly","Negotiated a plan around his creative goals"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Raju, 42: the auto driver''s first quarter at 7 am', 'lib-cr-089', 'guarded', '{"case_id":"cr-089","slug":"lib-cr-089","title":"Raju, 42: the auto driver''s first quarter at 7 am","difficulty":"guarded","traps":["adherence_fiction"],"traps_authored":["adherence_fiction"],"identity":{"name":"Raju Gaikwad","age":42,"gender":"male","occupation":"auto-rickshaw driver","city":"Pune (Hadapsar)","family_structure":"married, two children","language_register":"Marathi-Hindi, jokey, evasive"},"presentation":"Ten years of daily drinking, now a quarter of country liquor in the morning to stop the shaking, more through the day; failed attempts to cut down; lost earnings; wife''s complaint.","chief_complaint_in_own_words":"Saheb, a small one in the morning only, to settle the hands. Who doesn''t drink in this line?","history":{"timeline":"Drinking rose over ten years; morning drinking for two years; two failed attempts to stop.","substance_use":"country liquor, about 500 ml a day","medical":"gastritis","family":"father drank","treatment_history":"none","help_seeking_delay":"years","prior_contacts":["the wife","a de-addiction camp poster"]},"cognitive_model":{"core_belief":"I can stop when I want, but why should I?","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He shakes and sweats in the morning until the first drink.","gate":"two_or_more_reflective_statements"},{"fact":"His son saw him fall in the lane and has stopped talking to him.","gate":"validation_given"},{"fact":"He tried to stop twice and saw ''insects on the wall'' the second time.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Every driver drinks, ask anyone at the stand."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: some thoughts that his family would be better off without him when drunk; no plan. Withdrawal risk: previous visual disturbances suggest complicated withdrawal; needs medically supervised detox.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Quantified drinking and asked about withdrawal symptoms","Asked about past complicated withdrawal (seeing insects)","Used a non-judgemental, motivational tone","Asked about suicide clearly","Planned supervised detox with thiamine"],"few_shot":[],"fixture_lines":["Hands shake in the morning like this. One small one and the auto drives straight.","Two times I stopped. Second time, insects walking on the wall. Never again.","My son saw me fall in the gully. Since then, nothing. Not even ''Baba''.","Earning is less now. Morning I don''t go out until I''ve had one."],"variation":{"mood_today":["jokey","defensive","ashamed underneath"],"recent_event":["the wife went to her mother''s","a traffic fine","morning shakes worse"],"most_defended_topic":["his son''s silence"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["Marathi-Hindi, jokey, evasive"]},"moves":{},"module_id":"substance","voice_key":"Marathi-Hindi, jokey, evasive@Pune (Hadapsar)","protective_factors":["wife still with him","children"],"library":{"level":1,"topic":"substance","module":"substance","exams":["mcp-entrance","ma-semester","cuet-pg"],"objective":"Recognise the features of alcohol dependence","expected_mse":{"appearance":"Unshaven, smells of alcohol, tremor","behaviour":"Restless","speech":"Normal, jokey","mood":"''Fine, saheb''","affect":"Anxious, labile","thought_form":"Coherent","thought_content":"Minimisation, guilt about son","perception":"Past visual hallucinations in withdrawal","cognition":"Oriented","insight_judgement":"Poor insight"},"diagnosis":"Alcohol dependence with a history of complicated withdrawal","differentials":[{"dx":"Harmful use without dependence","why_not":"Morning drinking to relieve withdrawal, tolerance and failed attempts to stop show dependence"},{"dx":"Depressive disorder","why_not":"Low mood often improves once drinking stops; screen again after some weeks without alcohol"},{"dx":"Hepatic disease","why_not":"Heavy drinking damages the liver; check liver function as part of the physical work-up"}],"debrief_rubric":["Quantified drinking and asked about withdrawal symptoms","Asked about past complicated withdrawal (seeing insects)","Used a non-judgemental, motivational tone","Asked about suicide clearly","Planned supervised detox with thiamine"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Mr Nair, 58: day three after the knee operation', 'lib-cr-090', 'crisis', '{"case_id":"cr-090","slug":"lib-cr-090","title":"Mr Nair, 58: day three after the knee operation","difficulty":"crisis","traps":["medical_mimic","late_risk_reveal"],"traps_authored":["medical_mimic","late_risk_reveal"],"identity":{"name":"Prakash Nair","age":58,"gender":"male","occupation":"retired bank officer","city":"Thrissur","family_structure":"married; wife at bedside","language_register":"Malayalam-English, confused, frightened"},"presentation":"Third day after knee replacement: confused, agitated, sweating, tremulous, fast pulse, seeing snakes on the ceiling, pulling at his drip. Surgeon asks for ''sedation''. Wife reveals daily drinking that was not declared.","chief_complaint_in_own_words":"(pulling at the line) Snakes! On the ceiling! Why have you tied me? Let me go home.","history":{"timeline":"Admitted for elective surgery; last drink three days ago; symptoms started last night.","substance_use":"brandy about 375 ml daily for years, undisclosed","medical":"knee osteoarthritis, hypertension","family":"none","treatment_history":"postoperative painkillers","help_seeking_delay":"a day","prior_contacts":["the surgical team"]},"cognitive_model":{"core_belief":"(frightened) Someone is trying to hurt me.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"His wife says he drinks half a bottle of brandy every night and did not tell the surgeon.","gate":"asked_open_about_family"},{"fact":"He had shaking and sweating the morning after admission.","gate":"two_or_more_reflective_statements"},{"fact":"He had a seizure years ago when he stopped drinking on a pilgrimage.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["(confused) I''m fine, I''m at the bank."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":4},"affect_rules":{"on_interruption":"distress rises, repeats the last sentence","on_premature_advice":"says you are not listening","on_validation":"breathing slows and the story comes out","tts_rate":1.05,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: unable to engage meaningfully; no suicidal content. Medical emergency: delirium tremens risks seizures, falls, dehydration and death. Needs benzodiazepine-based treatment, thiamine before glucose, fluids, monitoring.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":true,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Took collateral history from the wife about drinking","Recognised delirium with autonomic signs","Recommended thiamine before glucose and a withdrawal regime rather than antipsychotic sedation alone","Considered other medical causes","Kept the patient safe and the environment calm","Assessed safety on the ward and the risk of falls and seizures"],"few_shot":[],"fixture_lines":["Snakes. There. Green ones.","Why am I tied? I''m a bank officer.","Leela, take me home. This hotel is bad.","My hands won''t stop. Too cold. Too hot."],"variation":{"mood_today":["frightened","agitated","confused"],"recent_event":["a nurse tried to give a tablet","the wife arrived","a loud trolley passed"],"most_defended_topic":["his drinking"],"opening_posture":["arrived in distress, cannot settle in the chair","brought in urgently, speaks in short bursts"],"somatic_focus":["none"],"trust_start":[2,3,4],"language_mix":["Malayalam-English, confused, frightened"]},"moves":{},"module_id":"substance","voice_key":"Malayalam-English, confused, frightened@Thrissur","protective_factors":["wife at bedside"],"library":{"level":5,"topic":"substance","module":"substance","exams":["md-psychiatry","mcp-entrance"],"objective":"Recognise alcohol withdrawal delirium on a surgical ward","expected_mse":{"appearance":"Sweating, tremulous, drip pulled","behaviour":"Agitated, picking at sheets","speech":"Slurred, rambling","mood":"Cannot describe","affect":"Fearful, labile","thought_form":"Disorganised","thought_content":"Persecutory ideas","perception":"Vivid visual hallucinations (snakes)","cognition":"Disoriented to place and time, inattentive","insight_judgement":"No insight"},"diagnosis":"Alcohol withdrawal delirium (delirium tremens)","differentials":[{"dx":"Postoperative delirium from other causes","why_not":"Infection, pain medicines, hypoxia: check, but timing after last drink and autonomic signs fit withdrawal"},{"dx":"Wernicke encephalopathy","why_not":"Wernicke can sit alongside withdrawal in heavy drinkers, so thiamine must be given anyway"},{"dx":"Primary psychosis","why_not":"Acute confusion with autonomic signs points to delirium"}],"debrief_rubric":["Took collateral history from the wife about drinking","Recognised delirium with autonomic signs","Recommended thiamine before glucose and a withdrawal regime rather than antipsychotic sedation alone","Considered other medical causes","Kept the patient safe and the environment calm","Assessed safety on the ward and the risk of falls and seizures"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Shankar, 50: walking like a sailor, eyes not moving right', 'lib-cr-091', 'crisis', '{"case_id":"cr-091","slug":"lib-cr-091","title":"Shankar, 50: walking like a sailor, eyes not moving right","difficulty":"crisis","traps":["medical_mimic","diagnostic_overshadowing"],"traps_authored":["medical_mimic","diagnostic_overshadowing"],"identity":{"name":"Shankar Das","age":50,"gender":"male","occupation":"daily wage labourer","city":"Kolkata (Howrah)","family_structure":"lives alone in a rented room","language_register":"Bengali, confused, apathetic"},"presentation":"Brought by a neighbour: weeks of heavy drinking with poor food, now confused, unsteady, double vision; on examination, nystagmus and ataxia.","chief_complaint_in_own_words":"Everything is two-two. And my legs don''t go straight.","history":{"timeline":"Drinking and not eating for weeks after losing work; confusion for three days.","substance_use":"country liquor daily, very little food","medical":"malnourished","family":"none","treatment_history":"none","help_seeking_delay":"days","prior_contacts":["a neighbour"]},"cognitive_model":{"core_belief":"(apathetic) Leave me.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"The neighbour says he has eaten only muri for weeks.","gate":"asked_open_about_family"},{"fact":"He vomited for days last week.","gate":"two_or_more_reflective_statements"},{"fact":"He cannot remember what day it is or why he is here.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["I''m only tired."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":4},"affect_rules":{"on_interruption":"distress rises, repeats the last sentence","on_premature_advice":"says you are not listening","on_validation":"breathing slows and the story comes out","tts_rate":1.05,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal content elicited; confused. Medical emergency: untreated Wernicke can progress to permanent memory loss (Korsakoff) or death. Needs high-dose parenteral thiamine now.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Recognised the triad: confusion, ataxia, eye signs (and that all three need not be present)","Asked about nutrition and vomiting","Urged parenteral thiamine before glucose immediately","Arranged medical admission","Kept a differential open for stroke and liver failure"],"few_shot":[],"fixture_lines":["Two-two. Two of you.","My legs... like a boat.","What day? I don''t know. Thursday?","Muri, little bit. And bangla."],"variation":{"mood_today":["apathetic","confused"],"recent_event":["fell in the lane","neighbour brought food","vomited again"],"most_defended_topic":["none"],"opening_posture":["arrived in distress, cannot settle in the chair","brought in urgently, speaks in short bursts"],"somatic_focus":["none"],"trust_start":[2,3,4],"language_mix":["Bengali, confused, apathetic"]},"moves":{},"module_id":"substance","voice_key":"Bengali, confused, apathetic@Kolkata (Howrah)","protective_factors":["caring neighbour"],"library":{"level":4,"topic":"substance","module":"substance","exams":["md-psychiatry","mcp-entrance"],"objective":"Recognise Wernicke encephalopathy and treat it urgently","expected_mse":{"appearance":"Thin, unkempt","behaviour":"Ataxic gait, nystagmus","speech":"Slow","mood":"Unable to describe","affect":"Apathetic","thought_form":"Slowed","thought_content":"Nil","perception":"Nil","cognition":"Disoriented, poor attention and recall","insight_judgement":"None"},"diagnosis":"Wernicke encephalopathy","differentials":[{"dx":"Alcohol withdrawal delirium","why_not":"No autonomic hyperactivity or hallucinations; ataxia and eye signs point to Wernicke"},{"dx":"Stroke","why_not":"Needs exclusion; signs are bilateral"},{"dx":"Hepatic encephalopathy","why_not":"Liver failure in heavy drinkers can also cause confusion; check liver function, though eye signs and ataxia point to Wernicke"}],"debrief_rubric":["Recognised the triad: confusion, ataxia, eye signs (and that all three need not be present)","Asked about nutrition and vomiting","Urged parenteral thiamine before glucose immediately","Arranged medical admission","Kept a differential open for stroke and liver failure"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Gopal, 45: the voices that come while he still drinks', 'lib-cr-092', 'guarded', '{"case_id":"cr-092","slug":"lib-cr-092","title":"Gopal, 45: the voices that come while he still drinks","difficulty":"guarded","traps":["substance_induced"],"traps_authored":["substance_induced"],"identity":{"name":"Gopal Chauhan","age":45,"gender":"male","occupation":"construction contractor","city":"Ahmedabad","family_structure":"married, three children","language_register":"Gujarati-Hindi, frightened, clear"},"presentation":"Heavy drinker; two weeks of hearing men threatening and abusing him, while fully alert and oriented, no tremor or confusion; terrified.","chief_complaint_in_own_words":"Men are talking about killing me. Outside the window, in the ceiling. I''m not drunk now, I swear.","history":{"timeline":"Twenty years of drinking; voices two weeks; still drinking but less.","substance_use":"whisky daily, reduced recently","medical":"fatty liver","family":"none","treatment_history":"none","help_seeking_delay":"two weeks","prior_contacts":["the wife"]},"cognitive_model":{"core_belief":"They will come for me.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"The voices say they will cut him and call him names.","gate":"two_or_more_reflective_statements"},{"fact":"He fears his children will be hurt.","gate":"validation_given"},{"fact":"He keeps a rod near his bed now.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["It''s not the drink, the drink makes it quiet."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Keeps a rod for defence: risk to others if he misreads someone as the attackers. Needs treatment and removal of the rod.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Checked orientation and attention to separate from delirium","Assessed risk to others and the rod","Asked about suicide clearly","Planned alcohol treatment and short-term antipsychotic with review"],"few_shot":[],"fixture_lines":["Two men. One rough voice, one thin. ''Tonight we finish him.''","I''m clear. I know the date. I know you''re the doctor.","I keep a rod near the bed. Just in case.","If they touch my children, I''ll do something."],"variation":{"mood_today":["frightened","clear"],"recent_event":["a sound at night","wife hid the rod","a payment due"],"most_defended_topic":["the rod"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["Gujarati-Hindi, frightened, clear"]},"moves":{},"module_id":"substance","voice_key":"Gujarati-Hindi, frightened, clear@Ahmedabad","protective_factors":["wife","children"],"library":{"level":4,"topic":"substance","module":"substance","exams":["md-psychiatry","mcp-entrance"],"objective":"Recognise alcohol-related hallucinosis with a clear sensorium","expected_mse":{"appearance":"Neat, mild smell of alcohol","behaviour":"Tense, looks at window","speech":"Normal","mood":"''Scared''","affect":"Fearful","thought_form":"Coherent","thought_content":"Persecutory ideas secondary to voices","perception":"Threatening voices in clear consciousness","cognition":"Oriented, attentive","insight_judgement":"Partial"},"diagnosis":"Alcohol-induced psychotic disorder (alcoholic hallucinosis)","differentials":[{"dx":"Delirium tremens","why_not":"Consciousness is clear and no autonomic signs"},{"dx":"Schizophrenia","why_not":"Late onset with heavy drinking; follow course after abstinence"},{"dx":"Withdrawal-related perceptual disturbance","why_not":"Hallucinations are sustained, not brief, with clear sensorium"}],"debrief_rubric":["Checked orientation and attention to separate from delirium","Assessed risk to others and the rod","Asked about suicide clearly","Planned alcohol treatment and short-term antipsychotic with review"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Gurpreet, 24: the chitta and the farm', 'lib-cr-093', 'resistant', '{"case_id":"cr-093","slug":"lib-cr-093","title":"Gurpreet, 24: the chitta and the farm","difficulty":"resistant","traps":["adherence_fiction"],"traps_authored":["adherence_fiction"],"identity":{"name":"Gurpreet Singh","age":24,"gender":"male","occupation":"unemployed, family farm","city":"Tarn Taran","family_structure":"lives with parents; brother in Canada","language_register":"Punjabi, sullen, sharp"},"presentation":"Three years of smoking then injecting heroin (''chitta''); tolerance, withdrawal, stealing from home; mother brought him.","chief_complaint_in_own_words":"Mummy dragged me. I don''t need a hospital. I''ll leave it myself.","history":{"timeline":"Started with friends after failing Class 12; injecting for a year.","substance_use":"heroin, injecting, shares needles sometimes","medical":"abscess on arm","family":"father drinks","treatment_history":"a private ''nasha mukti'' centre where he was beaten","help_seeking_delay":"three years","prior_contacts":["a private rehab"]},"cognitive_model":{"core_belief":"No one gets out of chitta.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He stole his mother''s gold earrings last month.","gate":"two_or_more_reflective_statements"},{"fact":"At the rehab centre he was chained and beaten.","gate":"validation_given"},{"fact":"He shares needles with two friends.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["I''ll stop myself, just give me sleeping tablets."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"pushes back sharply","on_premature_advice":"dismisses it and questions the point of coming","on_validation":"goes quiet, then softens a little","tts_rate":0.9,"tts_pitch":0.9},"red_flags":[{"content":"Asked clearly: thoughts of ''going with an overdose, who cares'' when craving; no plan. High overdose risk; needs naloxone access, HIV and hepatitis testing, and treatment.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":true,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Asked about route, amount, withdrawal and injecting risks","Acknowledged the harm done by the forced rehab","Asked about suicide and overdose clearly","Explained opioid substitution treatment options","Offered testing and harm reduction"],"few_shot":[],"fixture_lines":["First it was smoking on foil. Now the needle. Faster.","Mummy''s earrings. I''ll get them back. I will.","That centre chained us. Beat us. You want me to go back?","Without it, bones break from inside. Nose runs, stomach turns."],"variation":{"mood_today":["sullen","craving","ashamed"],"recent_event":["a friend overdosed","police raid in the village","mother''s tears"],"most_defended_topic":["stealing from his mother"],"opening_posture":["arms folded, says this visit was not their idea","challenges why the questions are needed"],"somatic_focus":["none"],"trust_start":[2,3],"language_mix":["Punjabi, sullen, sharp"]},"moves":{},"module_id":"substance","voice_key":"Punjabi, sullen, sharp@Tarn Taran","protective_factors":["mother''s persistence"],"library":{"level":2,"topic":"substance","module":"substance","exams":["mcp-entrance","ma-semester","cuet-pg"],"objective":"Recall the features of opioid dependence","expected_mse":{"appearance":"Thin, track marks, abscess","behaviour":"Restless, yawning","speech":"Short, sharp","mood":"''Fine''","affect":"Irritable","thought_form":"Coherent","thought_content":"Hopelessness about recovery","perception":"Nil","cognition":"Intact","insight_judgement":"Partial"},"diagnosis":"Opioid dependence (heroin), injecting","differentials":[{"dx":"Harmful use only","why_not":"Tolerance, withdrawal and loss of control indicate dependence"},{"dx":"Depressive disorder","why_not":"Low mood and hopelessness often sit alongside opioid dependence; screen now and again once stable"},{"dx":"Other drug use","why_not":"People using heroin often add sedative tablets or alcohol, which raises overdose risk; ask directly"}],"debrief_rubric":["Asked about route, amount, withdrawal and injecting risks","Acknowledged the harm done by the forced rehab","Asked about suicide and overdose clearly","Explained opioid substitution treatment options","Offered testing and harm reduction"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Feroz, 30: yawning, sweating, gooseflesh', 'lib-cr-094', 'crisis', '{"case_id":"cr-094","slug":"lib-cr-094","title":"Feroz, 30: yawning, sweating, gooseflesh","difficulty":"crisis","traps":[],"traps_authored":[],"identity":{"name":"Feroz Khan","age":30,"gender":"male","occupation":"tailor","city":"Delhi (Seelampur)","family_structure":"married, two children","language_register":"Delhi Urdu, desperate"},"presentation":"Last heroin use 18 hours ago; yawning, runny nose, tearing, gooseflesh, dilated pupils, abdominal cramps, diarrhoea, body ache, craving; asks for help.","chief_complaint_in_own_words":"Bhai, help me. Body is breaking. Nose, eyes, stomach. Give something.","history":{"timeline":"Used daily for five years; trying to stop after his wife''s ultimatum.","substance_use":"heroin smoked daily","medical":"none","family":"none","treatment_history":"none","help_seeking_delay":"years","prior_contacts":["the wife"]},"cognitive_model":{"core_belief":"I can''t do this without help.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"His wife said she will leave with the children if he uses again.","gate":"two_or_more_reflective_statements"},{"fact":"He wants to stop for his daughter.","gate":"validation_given"},{"fact":"He tried alone twice and lasted two days.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Just this once give me something strong."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":4},"affect_rules":{"on_interruption":"distress rises, repeats the last sentence","on_premature_advice":"says you are not listening","on_validation":"breathing slows and the story comes out","tts_rate":1.05,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Opioid withdrawal is rarely fatal but very distressing; relapse after withdrawal carries high overdose risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Identified the objective signs of withdrawal","Explained treatment options (buprenorphine or methadone, symptomatic relief)","Warned about lowered tolerance and overdose after detox","Used his motivation","Gave psychoeducation about withdrawal and the risk of overdose after it"],"few_shot":[],"fixture_lines":["Nose running like a tap. Eyes watering. Hair standing.","Stomach twisting. Toilet ten times.","My bones ache like someone is beating them.","My daughter. For her I want to stop."],"variation":{"mood_today":["desperate","motivated"],"recent_event":["wife''s ultimatum","daughter''s birthday","a dealer''s call"],"most_defended_topic":["past failures"],"opening_posture":["arrived in distress, cannot settle in the chair","brought in urgently, speaks in short bursts"],"somatic_focus":["none"],"trust_start":[2,3,4],"language_mix":["Delhi Urdu, desperate"]},"moves":{},"module_id":"substance","voice_key":"Delhi Urdu, desperate@Delhi (Seelampur)","protective_factors":["motivation for his daughter","wife"],"library":{"level":1,"topic":"substance","module":"substance","exams":["mcp-entrance","ma-semester","cuet-pg"],"objective":"Recognise opioid withdrawal signs","expected_mse":{"appearance":"Sweating, gooseflesh, dilated pupils","behaviour":"Restless, yawning","speech":"Pleading","mood":"''Breaking''","affect":"Anxious, dysphoric","thought_form":"Coherent","thought_content":"Craving","perception":"Nil","cognition":"Intact","insight_judgement":"Good"},"diagnosis":"Opioid withdrawal (in opioid dependence)","differentials":[{"dx":"Gastroenteritis","why_not":"Pupils, gooseflesh, yawning and craving point to withdrawal"},{"dx":"Alcohol withdrawal","why_not":"Different pattern; ask about alcohol"},{"dx":"Anxiety","why_not":"Clear physical withdrawal signs"}],"debrief_rubric":["Identified the objective signs of withdrawal","Explained treatment options (buprenorphine or methadone, symptomatic relief)","Warned about lowered tolerance and overdose after detox","Used his motivation","Gave psychoeducation about withdrawal and the risk of overdose after it"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Harjit, 35: the tablet under the tongue, every day for a year', 'lib-cr-095', 'cooperative', '{"case_id":"cr-095","slug":"lib-cr-095","title":"Harjit, 35: the tablet under the tongue, every day for a year","difficulty":"cooperative","traps":[],"traps_authored":[],"identity":{"name":"Harjit Kaur","age":35,"gender":"female","occupation":"beautician","city":"Amritsar","family_structure":"widowed, one son","language_register":"Punjabi, steady"},"presentation":"On buprenorphine maintenance for a year after opioid dependence; stable, working; relatives say she is ''still addicted'' and should stop.","chief_complaint_in_own_words":"My relatives say I''m still an addict because I take this tablet. Should I stop it?","history":{"timeline":"Used opioids after her husband''s death; stable a year on maintenance.","substance_use":"none now; previously heroin","medical":"none","family":"none","treatment_history":"buprenorphine at a government OST centre","help_seeking_delay":"none","prior_contacts":["OST centre"]},"cognitive_model":{"core_belief":"Maybe they are right.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She has not used heroin for a year.","gate":"two_or_more_reflective_statements"},{"fact":"She feels ashamed at family functions.","gate":"validation_given"},{"fact":"She thought of tapering quickly on her own.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Maybe I should prove I''m strong."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Risk: rapid unplanned stopping raises relapse and overdose risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Explained maintenance treatment as evidence-based, not ''still addicted''","Discussed relapse and overdose risk with rapid stopping","Supported a planned decision","Asked about suicide clearly"],"few_shot":[],"fixture_lines":["One year clean. I opened my own parlour.","My sister-in-law says, ''still on the tablet, still addicted''.","My son is ten. He''s proud of me.","I thought of stopping fast, like they say."],"variation":{"mood_today":["steady","doubtful"],"recent_event":["a wedding","sister-in-law''s comment","OST review"],"most_defended_topic":["shame at functions"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["Punjabi, steady"]},"moves":{},"module_id":"substance","voice_key":"Punjabi, steady@Amritsar","protective_factors":["son","business"],"library":{"level":3,"topic":"substance","module":"substance","exams":["mcp-entrance","md-psychiatry"],"objective":"Discuss opioid agonist maintenance and stigma","expected_mse":{"appearance":"Neat","behaviour":"Calm","speech":"Normal","mood":"''Okay''","affect":"Euthymic","thought_form":"Coherent","thought_content":"Doubt about treatment","perception":"Nil","cognition":"Intact","insight_judgement":"Good"},"diagnosis":"Opioid dependence in sustained remission on maintenance treatment","differentials":[{"dx":"Active addiction","why_not":"Stable dose under supervision with function restored is treatment, not addiction"},{"dx":"Ready for taper","why_not":"Possible later, slowly and by plan"},{"dx":"Depression","why_not":"Shame and criticism from relatives can bring low mood, which raises relapse risk; ask about it"}],"debrief_rubric":["Explained maintenance treatment as evidence-based, not ''still addicted''","Discussed relapse and overdose risk with rapid stopping","Supported a planned decision","Asked about suicide clearly"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Mr Saini, 48: the painkiller from the chemist', 'lib-cr-096', 'guarded', '{"case_id":"cr-096","slug":"lib-cr-096","title":"Mr Saini, 48: the painkiller from the chemist","difficulty":"guarded","traps":["iatrogenic"],"traps_authored":["iatrogenic"],"identity":{"name":"Rakesh Saini","age":48,"gender":"male","occupation":"truck driver","city":"Jaipur","family_structure":"married, three children","language_register":"Rajasthani Hindi, matter-of-fact"},"presentation":"Takes tramadol bought from chemists, now 8 to 10 tablets a day, for back pain and ''energy'' on long hauls; recent seizure on the highway.","chief_complaint_in_own_words":"Back pain, saheb. The tablet keeps me driving. But last month I had a fit at a dhaba.","history":{"timeline":"Started for back pain two years ago; dose escalated; seizure last month.","substance_use":"tramadol 8 to 10 tablets daily, alcohol at night sometimes","medical":"back pain, seizure last month","family":"none","treatment_history":"chemist","help_seeking_delay":"two years","prior_contacts":["chemists on the highway"]},"cognitive_model":{"core_belief":"Without it I can''t do the long trips.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He takes ten tablets on long trips.","gate":"two_or_more_reflective_statements"},{"fact":"He fears losing his licence.","gate":"validation_given"},{"fact":"He sometimes drinks at night with the tablets.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["It''s only a painkiller."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Risk: seizures, road accidents, interaction with alcohol.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Quantified use and escalation","Explained seizure risk of high-dose tramadol","Discussed driving safety honestly","Planned supervised taper and pain management"],"few_shot":[],"fixture_lines":["Jaipur to Kolkata, three days. Without the tablet, impossible.","Last month at a dhaba, I fell and shook. The cleaner boy saw.","Every chemist on the highway knows me.","If they take my licence, my family starves."],"variation":{"mood_today":["matter-of-fact","worried"],"recent_event":["a long trip booked","another seizure aura","licence renewal"],"most_defended_topic":["fear of losing licence"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["Rajasthani Hindi, matter-of-fact"]},"moves":{},"module_id":"substance","voice_key":"Rajasthani Hindi, matter-of-fact@Jaipur","protective_factors":["family he provides for"],"library":{"level":3,"topic":"substance","module":"substance","exams":["mcp-entrance","md-psychiatry"],"objective":"Recognise tramadol dependence and seizure risk","expected_mse":{"appearance":"Weathered","behaviour":"Calm","speech":"Normal","mood":"''Worried''","affect":"Anxious","thought_form":"Coherent","thought_content":"Minimisation","perception":"Nil","cognition":"Intact","insight_judgement":"Partial"},"diagnosis":"Opioid (tramadol) dependence with tramadol-related seizure","differentials":[{"dx":"Epilepsy","why_not":"Seizure linked to high tramadol dose"},{"dx":"Alcohol withdrawal seizure","why_not":"Possible contributor; ask timing"},{"dx":"Chronic pain alone","why_not":"Escalation, craving and use for energy show dependence"}],"debrief_rubric":["Quantified use and escalation","Explained seizure risk of high-dose tramadol","Discussed driving safety honestly","Planned supervised taper and pain management"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Rina, 19: the cough syrup bottles under the bed', 'lib-cr-097', 'guarded', '{"case_id":"cr-097","slug":"lib-cr-097","title":"Rina, 19: the cough syrup bottles under the bed","difficulty":"guarded","traps":[],"traps_authored":[],"identity":{"name":"Rina Barman","age":19,"gender":"female","occupation":"first-year college student","city":"Siliguri","family_structure":"lives with mother","language_register":"Bengali-Hindi, shy, defensive"},"presentation":"Mother found many empty codeine cough syrup bottles; daughter drinks two bottles a day, feels low and irritable without it, constipated, failing classes.","chief_complaint_in_own_words":"It''s just cough syrup. Everyone takes it. Mummy is making a big drama.","history":{"timeline":"Started with friends a year ago; now two bottles a day.","substance_use":"codeine syrup two bottles a day","medical":"constipation","family":"father left the family","treatment_history":"none","help_seeking_delay":"a year","prior_contacts":["friends"]},"cognitive_model":{"core_belief":"It''s the only thing that makes me feel calm.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"Without it she aches, sweats and cannot sleep.","gate":"two_or_more_reflective_statements"},{"fact":"She feels her father''s leaving was her fault.","gate":"validation_given"},{"fact":"She spends her fee money on bottles.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["It''s medicine, not a drug."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: some low feelings, no suicidal plan. Moderate risk; monitor.","gate":"asked_about_self_harm_clearly"}],"contex