ance":[]},"style_refs":[],"rubric_targets":["Used a non-judgemental, curious stance","Asked about withdrawal and impact","Explored pressures behind use","Asked about suicide clearly","Explained confidentiality limits"],"few_shot":[],"fixture_lines":["It''s legal in Canada, bro.","Football''s boring now. Everything''s meh.","When I don''t smoke I can''t sleep. Then I''m angry.","Dad wants IIT. I want, like, peace."],"variation":{"mood_today":["laid-back","irritable"],"recent_event":["board exam timetable","football trials","parents searched his room"],"most_defended_topic":["pressure from father"],"opening_posture":["arms folded, says this visit was not their idea","challenges why the questions are needed"],"somatic_focus":["none"],"trust_start":[2,3],"language_mix":["laid-back English, shrugs"]},"moves":{},"module_id":"substance","voice_key":"laid-back English, shrugs@Chandigarh","protective_factors":["school counsellor","parents'' concern"],"library":{"level":2,"topic":"substance","module":"substance","exams":["mcp-entrance","ma-semester","cuet-pg"],"objective":"Recall cannabis use disorder and its effect on motivation","expected_mse":{"appearance":"Casual","behaviour":"Slouched","speech":"Laconic","mood":"''Fine''","affect":"Restricted","thought_form":"Coherent","thought_content":"Minimisation","perception":"Nil","cognition":"Intact","insight_judgement":"Poor"},"diagnosis":"Cannabis use disorder","differentials":[{"dx":"Depression","why_not":"Screen; anhedonia could be either"},{"dx":"Normal adolescent experimentation","why_not":"Daily use, withdrawal and functional decline exceed it"},{"dx":"Psychosis","why_not":"Cannabis can cause psychosis, but he has no unusual beliefs or voices"}],"debrief_rubric":["Used a non-judgemental, curious stance","Asked about withdrawal and impact","Explored pressures behind use","Asked about suicide clearly","Explained confidentiality limits"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = exclu