insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Chhotu, 13: the cloth and the whitener', 'lib-cr-099', 'guarded', '{"case_id":"cr-099","slug":"lib-cr-099","title":"Chhotu, 13: the cloth and the whitener","difficulty":"guarded","traps":[],"traps_authored":[],"identity":{"name":"Chhotu","age":13,"gender":"male","occupation":"rag picker at the railway station","city":"Delhi (New Delhi station)","family_structure":"ran away from home in Bihar; lives with other boys","language_register":"Bhojpuri-Hindi, streetwise, guarded"},"presentation":"Brought by an NGO worker: sniffs correction fluid on a cloth daily; headaches, poor memory, falls; lives on the platform.","chief_complaint_in_own_words":"Didi brought me. I''m fine. The solution takes away hunger and cold.","history":{"timeline":"Ran away at ten after beatings by his stepfather; sniffing for two years.","substance_use":"inhalants daily, sometimes bidis","medical":"headaches, a burn scar","family":"stepfather violent","treatment_history":"none","help_seeking_delay":"two years","prior_contacts":["NGO outreach worker"]},"cognitive_model":{"core_belief":"Nobody cares about me.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He sniffs to stop feeling hungry and cold at night.","gate":"two_or_more_reflective_statements"},{"fact":"He ran from home after his stepfather beat him.","gate":"validation_given"},{"fact":"Older boys sometimes take his money and hurt him.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Everyone at the station does it."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: sometimes wishes he was dead, no plan. Child protection concern: abuse and exploitation. Inhalants risk sudden death. Needs child welfare referral.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":["Juvenile Justice Act","POCSO Act"]},"style_refs":[],"rubric_targets":["Built trust before asking hard questions","Asked about abuse and exploitation sensitively","Asked about suicide clearly","Linked with child welfare and NGO support","Explained inhalant risks simply"],"few_shot":[],"fixture_lines":["One whitener, one cloth. Hunger gone, cold gone.","Bihar? No. Stepfather beats.","Big boys take my money. Sometimes worse.","Didi is good. She brings rotis."],"variation":{"mood_today":["guarded","tough"],"recent_event":["police chased them","cold night","NGO shelter visit"],"most_defended_topic":["what older boys do"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["Bhojpuri-Hindi, streetwise, guarded"]},"moves":{},"module_id":"substance","voice_key":"Bhojpuri-Hindi, streetwise, guarded@Delhi (New Delhi station)","protective_factors":["NGO worker"],"library":{"level":3,"topic":"substance","module":"substance","exams":["mcp-entrance","ma-semester"],"objective":"Assess inhalant use in a street-connected child","expected_mse":{"appearance":"Thin, dirty clothes, solvent smell","behaviour":"Watchful","speech":"Short","mood":"''Fine''","affect":"Restricted","thought_form":"Coherent","thought_content":"Mistrust","perception":"Nil","cognition":"Poor recall","insight_judgement":"Limited"},"diagnosis":"Inhalant use disorder in a street-connected child with safeguarding concerns","differentials":[{"dx":"Neurocognitive effects of inhalants","why_not":"Memory and headaches suggest toxicity; needs medical review"},{"dx":"Post-traumatic stress","why_not":"History of abuse; screen gently"},{"dx":"Depression","why_not":"Children who run from violence often carry low mood; screen gently once trust is built"}],"debrief_rubric":["Built trust before asking hard questions","Asked about abuse and exploitation sensitively","Asked about suicide clearly","Linked with child welfare and NGO support","Explained inhalant risks simply"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Mr Venkat, 55: twenty years of beedis', 'lib-cr-100', 'cooperative', '{"case_id":"cr-100","slug":"lib-cr-100","title":"Mr Venkat, 55: twenty years of beedis","difficulty":"cooperative","traps":[],"traps_authored":[],"identity":{"name":"Venkatesh","age":55,"gender":"male","occupation":"weaver","city":"Kanchipuram","family_structure":"married, two daughters","language_register":"Tamil, polite"},"presentation":"Smokes 25 beedis a day for twenty years; recent bronchitis; doctor advised stopping; ambivalent.","chief_complaint_in_own_words":"Doctor says stop. My lungs are tired. But beedi is my company while weaving.","history":{"timeline":"Smoking since 20; tried stopping once for a week.","substance_use":"beedis 25 a day","medical":"chronic bronchitis","family":"father died of lung disease","treatment_history":"none","help_seeking_delay":"years","prior_contacts":["doctor"]},"cognitive_model":{"core_belief":"Weaving without beedi is impossible.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He smokes most during long weaving hours.","gate":"two_or_more_reflective_statements"},{"fact":"His father died coughing.","gate":"validation_given"},{"fact":"His granddaughter asked him to stop.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Beedi is less harmful than cigarettes."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Low risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Used the 5 As or a brief motivational approach","Explored his reasons for and against","Corrected the beedi myth","Offered nicotine replacement and a quit date"],"few_shot":[],"fixture_lines":["Twenty-five beedis. One for every row.","My father died coughing. I hear it in my own chest now.","My granddaughter said, ''Thatha, your smell is bad''.","Once I stopped for a week. Very irritable."],"variation":{"mood_today":["polite","ambivalent"],"recent_event":["a cough at night","granddaughter''s visit","silk order deadline"],"most_defended_topic":["father''s death"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["Tamil, polite"]},"moves":{},"module_id":"substance","voice_key":"Tamil, polite@Kanchipuram","protective_factors":["granddaughter","family"],"library":{"level":1,"topic":"substance","module":"substance","exams":["mcp-entrance","ma-semester","cuet-pg"],"objective":"Use a brief intervention for tobacco cessation","expected_mse":{"appearance":"Thin, coughs","behaviour":"Calm","speech":"Normal","mood":"''Okay''","affect":"Euthymic","thought_form":"Coherent","thought_content":"Ambivalence","perception":"Nil","cognition":"Intact","insight_judgement":"Partial"},"diagnosis":"Tobacco (nicotine) dependence","differentials":[{"dx":"Social habit only","why_not":"Withdrawal and heavy use show dependence"},{"dx":"COPD","why_not":"His lung disease is a complication of smoking and needs its own assessment"},{"dx":"Depression","why_not":"Low mood can make quitting harder and nicotine withdrawal can lower mood briefly; ask about it"}],"debrief_rubric":["Used the 5 As or a brief motivational approach","Explored his reasons for and against","Corrected the beedi myth","Offered nicotine replacement and a quit date"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Vishal, 29: the rummy app at 3 am', 'lib-cr-101', 'guarded', '{"case_id":"cr-101","slug":"lib-cr-101","title":"Vishal, 29: the rummy app at 3 am","difficulty":"guarded","traps":["late_risk_reveal"],"traps_authored":["late_risk_reveal"],"identity":{"name":"Vishal Patil","age":29,"gender":"male","occupation":"bank cashier","city":"Nagpur","family_structure":"married eight months","language_register":"Marathi-Hindi, ashamed"},"presentation":"A year of online card gambling, chasing losses, borrowing from apps and friends, hiding debts of six lakh, lying to his wife.","chief_complaint_in_own_words":"I''m in a big loan problem. My wife doesn''t know. The rummy app took everything.","history":{"timeline":"Started with small bets during the lockdown; escalated after a big win; chasing losses.","substance_use":"none","medical":"none","family":"uncle gambled","treatment_history":"none","help_seeking_delay":"a year","prior_contacts":["loan app agents"]},"cognitive_model":{"core_belief":"One big win will fix everything.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He took loans from six apps; agents call his colleagues.","gate":"two_or_more_reflective_statements"},{"fact":"He hides it from his new wife and feels he has cheated her.","gate":"validation_given"},{"fact":"He took money from the cash counter once and replaced it.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["It''s a game of skill, not gambling."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: thoughts of suicide when loan agents threatened to shame him; no plan. Moderate to high risk; gambling and debt are strongly linked to suicide.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Asked about chasing losses, lying and debts","Asked about suicide clearly","Asked about the legal and job risk sensitively","Planned financial controls and support, including telling his wife with help"],"few_shot":[],"fixture_lines":["First win was 40,000. I thought, I''m good at this.","Now I play to win back. Always to win back.","Six loan apps. Agents call my office.","My wife thinks the phone calls are spam."],"variation":{"mood_today":["ashamed","anxious"],"recent_event":["an agent threatened to call his wife","a salary day","a loss streak"],"most_defended_topic":["the cash counter"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["Marathi-Hindi, ashamed"]},"moves":{},"module_id":"substance","voice_key":"Marathi-Hindi, ashamed@Nagpur","protective_factors":["wife","job"],"library":{"level":2,"topic":"substance","module":"substance","exams":["mcp-entrance","ma-semester","cuet-pg"],"objective":"Recall the features of gambling disorder","expected_mse":{"appearance":"Neat","behaviour":"Restless","speech":"Normal","mood":"''Trapped''","affect":"Anxious, low","thought_form":"Coherent","thought_content":"Debt worries, hope of big win","perception":"Nil","cognition":"Intact","insight_judgement":"Partial"},"diagnosis":"Gambling disorder","differentials":[{"dx":"Bipolar disorder","why_not":"Gambling not limited to high mood episodes"},{"dx":"Depressive disorder","why_not":"Low mood often follows heavy losses and debt; screen for it"},{"dx":"Recreational gaming","why_not":"Chasing losses, lying and debt show disorder"}],"debrief_rubric":["Asked about chasing losses, lying and debts","Asked about suicide clearly","Asked about the legal and job risk sensitively","Planned financial controls and support, including telling his wife with help"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Aarav, 15: the game that ate his nights', 'lib-cr-102', 'resistant', '{"case_id":"cr-102","slug":"lib-cr-102","title":"Aarav, 15: the game that ate his nights","difficulty":"resistant","traps":["under_diagnosis"],"traps_authored":["under_diagnosis"],"identity":{"name":"Aarav Gupta","age":15,"gender":"male","occupation":"Class 10 student","city":"Gurugram","family_structure":"lives with working parents","language_register":"teen English, monosyllabic"},"presentation":"Plays an online shooter 8 to 10 hours daily for a year; stopped school attendance for a month; aggressive when the router is switched off.","chief_complaint_in_own_words":"There''s nothing else to do. My parents are never home anyway.","history":{"timeline":"Gaming increased after moving schools; school refusal for a month.","substance_use":"energy drinks","medical":"none","family":"parents both work late","treatment_history":"none","help_seeking_delay":"a year","prior_contacts":["school counsellor"]},"cognitive_model":{"core_belief":"In the game, I''m someone.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He has no friends at the new school; his game squad are his friends.","gate":"two_or_more_reflective_statements"},{"fact":"He feels his parents only notice his marks.","gate":"validation_given"},{"fact":"He broke his father''s phone when the router was turned off.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Everyone games."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"pushes back sharply","on_premature_advice":"dismisses it and questions the point of coming","on_validation":"goes quiet, then softens a little","tts_rate":0.9,"tts_pitch":0.9},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Low risk; aggression at home.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Asked about loss of control and priority given to gaming","Explored the school move and loneliness","Asked about suicide clearly","Planned family work rather than only removing devices"],"few_shot":[],"fixture_lines":["My squad''s online at 10 pm. Every night.","New school, nobody talks to me.","They switched off the router. I lost it.","In the game I''m rank Diamond. At school I''m no one."],"variation":{"mood_today":["monosyllabic","irritable"],"recent_event":["router off","school''s warning","game tournament"],"most_defended_topic":["breaking the phone"],"opening_posture":["arms folded, says this visit was not their idea","challenges why the questions are needed"],"somatic_focus":["none"],"trust_start":[2,3],"language_mix":["teen English, monosyllabic"]},"moves":{},"module_id":"child","voice_key":"teen English, monosyllabic@Gurugram","protective_factors":["online friendships","parents'' concern"],"library":{"level":3,"topic":"substance","module":"child","exams":["mcp-entrance","ma-semester"],"objective":"Apply criteria for gaming disorder","expected_mse":{"appearance":"Hoodie, pale","behaviour":"Slouched","speech":"Minimal","mood":"''Bored''","affect":"Irritable","thought_form":"Coherent","thought_content":"Low self-worth offline","perception":"Nil","cognition":"Intact","insight_judgement":"Poor"},"diagnosis":"Gaming disorder","differentials":[{"dx":"Depression","why_not":"Screen; isolation may be primary"},{"dx":"Social anxiety","why_not":"Fear of judgement at the new school may lie behind the avoidance; ask about it"},{"dx":"ADHD","why_not":"Ask about lifelong attention problems"}],"debrief_rubric":["Asked about loss of control and priority given to gaming","Explored the school move and loneliness","Asked about suicide clearly","Planned family work rather than only removing devices"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Sujata, 46: the vodka in the water bottle', 'lib-cr-103', 'guarded', '{"case_id":"cr-103","slug":"lib-cr-103","title":"Sujata, 46: the vodka in the water bottle","difficulty":"guarded","traps":["somatic_mask","iatrogenic"],"traps_authored":["somatic_mask","iatrogenic"],"identity":{"name":"Sujata Rao","age":46,"gender":"female","occupation":"interior designer","city":"Hyderabad","family_structure":"married, two teenage children","language_register":"polished English, guarded"},"presentation":"Presents with insomnia and ''anxiety''; on gentle questioning, drinks vodka from a water bottle through the day, blackouts, a recent fall.","chief_complaint_in_own_words":"I can''t sleep and I''m anxious. Maybe a sleeping tablet?","history":{"timeline":"Drinking escalated after her mother''s death three years ago; hidden from family.","substance_use":"vodka about half a bottle a day","medical":"raised liver enzymes, a fall","family":"father drank","treatment_history":"none","help_seeking_delay":"years","prior_contacts":["GP for sleep"]},"cognitive_model":{"core_belief":"A woman who drinks is a disgrace.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She keeps vodka in a water bottle in her bag.","gate":"two_or_more_reflective_statements"},{"fact":"Her mother''s death left her with no one to talk to.","gate":"validation_given"},{"fact":"She had a blackout and doesn''t remember driving home.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["I''m a social drinker at parties only."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: passive thoughts on bad mornings, no plan. Risks: drink driving, falls; combining alcohol with sleeping tablets would be dangerous.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Asked about alcohol routinely and without judgement","Recognised the danger of prescribing sedatives","Asked about driving and blackouts","Asked about suicide clearly","Addressed stigma for women who drink"],"few_shot":[],"fixture_lines":["I can''t sleep. My mind won''t switch off.","My water bottle... it''s not always water.","Since Amma died, I don''t have anyone to call at night.","I don''t remember driving home last Friday."],"variation":{"mood_today":["guarded","ashamed"],"recent_event":["a client dinner","husband found a bottle","a near accident"],"most_defended_topic":["the water bottle"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["polished English, guarded"]},"moves":{},"module_id":"substance","voice_key":"polished English, guarded@Hyderabad","protective_factors":["children","career"],"library":{"level":3,"topic":"substance","module":"substance","exams":["mcp-entrance","md-psychiatry"],"objective":"Detect hidden drinking in a woman and the stigma that hides it","expected_mse":{"appearance":"Elegant, mint smell","behaviour":"Restless","speech":"Polished","mood":"''Anxious''","affect":"Anxious, low","thought_form":"Coherent","thought_content":"Shame","perception":"Nil","cognition":"Intact","insight_judgement":"Partial"},"diagnosis":"Alcohol dependence presenting as insomnia and anxiety","differentials":[{"dx":"Generalised anxiety disorder","why_not":"Anxiety may be withdrawal-related; reassess after abstinence"},{"dx":"Depression","why_not":"Grief and low mood may sit under her drinking; screen now and after a period without alcohol"},{"dx":"Prolonged grief","why_not":"Mother''s death relevant; assess"}],"debrief_rubric":["Asked about alcohol routinely and without judgement","Recognised the danger of prescribing sedatives","Asked about driving and blackouts","Asked about suicide clearly","Addressed stigma for women who drink"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Prakash, 52: the liver doctor sent him', 'lib-cr-104', 'resistant', '{"case_id":"cr-104","slug":"lib-cr-104","title":"Prakash, 52: the liver doctor sent him","difficulty":"resistant","traps":["adherence_fiction"],"traps_authored":["adherence_fiction"],"identity":{"name":"Prakash Hegde","age":52,"gender":"male","occupation":"hotel owner","city":"Udupi","family_structure":"married, one son","language_register":"Kannada-English, proud"},"presentation":"Alcoholic liver disease diagnosed; hepatologist referred; drinks three to four pegs nightly; believes he can cut down himself.","chief_complaint_in_own_words":"The liver doctor is exaggerating. I''ll cut down to two pegs. Problem solved.","history":{"timeline":"Drinking thirty years; liver scan shows cirrhosis starting.","substance_use":"whisky three to four pegs nightly","medical":"early cirrhosis, low platelets","family":"none","treatment_history":"none","help_seeking_delay":"years","prior_contacts":["hepatologist"]},"cognitive_model":{"core_belief":"I''m in control.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He has tried cutting down three times and gone back.","gate":"two_or_more_reflective_statements"},{"fact":"He wants to see his son''s wedding.","gate":"validation_given"},{"fact":"His wife has started sleeping in another room.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["The doctor wants to scare me."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"pushes back sharply","on_premature_advice":"dismisses it and questions the point of coming","on_validation":"goes quiet, then softens a little","tts_rate":0.9,"tts_pitch":0.9},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Physical risk from cirrhosis.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Used reflective listening rather than confrontation","Elicited his own reasons to change (son''s wedding)","Developed discrepancy gently","Offered options including medicines that support abstinence safely with liver disease","Validated his pride while exploring the cost of drinking"],"few_shot":[],"fixture_lines":["Two pegs is nothing. My grandfather drank till ninety.","Three times I said I''ll cut. Then the hotel''s evening crowd.","My son''s marriage is next year. I''ll be there, don''t worry.","My wife sleeps in the guest room now."],"variation":{"mood_today":["proud","defensive"],"recent_event":["a liver test","son''s engagement","a hotel party"],"most_defended_topic":["wife moving out of the room"],"opening_posture":["arms folded, says this visit was not their idea","challenges why the questions are needed"],"somatic_focus":["none"],"trust_start":[2,3],"language_mix":["Kannada-English, proud"]},"moves":{},"module_id":"substance","voice_key":"Kannada-English, proud@Udupi","protective_factors":["son","wife"],"library":{"level":3,"topic":"substance","module":"substance","exams":["mcp-entrance","md-psychiatry"],"objective":"Use motivational interviewing with an ambivalent drinker","expected_mse":{"appearance":"Well dressed, mild jaundice","behaviour":"Calm","speech":"Confident","mood":"''Fine''","affect":"Euthymic","thought_form":"Coherent","thought_content":"Minimisation","perception":"Nil","cognition":"Intact","insight_judgement":"Poor"},"diagnosis":"Alcohol dependence with alcoholic liver disease","differentials":[{"dx":"Harmful use","why_not":"Failed attempts and continued use despite harm suggest dependence"},{"dx":"Depression","why_not":"Low mood is common in heavy drinkers and can block change; screen for it"},{"dx":"Other liver disease","why_not":"Other liver diseases are possible, but the hepatologist is managing that side"}],"debrief_rubric":["Used reflective listening rather than confrontation","Elicited his own reasons to change (son''s wedding)","Developed discrepancy gently","Offered options including medicines that support abstinence safely with liver disease","Validated his pride while exploring the cost of drinking"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Tushar, 33: the third time back from rehab', 'lib-cr-105', 'cooperative', '{"case_id":"cr-105","slug":"lib-cr-105","title":"Tushar, 33: the third time back from rehab","difficulty":"cooperative","traps":[],"traps_authored":[],"identity":{"name":"Tushar Mehta","age":33,"gender":"male","occupation":"software tester","city":"Pune","family_structure":"lives with parents","language_register":"articulate English, discouraged"},"presentation":"Relapsed to alcohol two weeks after a 90-day rehab, third time; craving in the evenings, old friends, office parties.","chief_complaint_in_own_words":"Three rehabs. Three relapses. Maybe I''m just weak.","history":{"timeline":"Each relapse within a month of discharge.","substance_use":"alcohol","medical":"none","family":"none","treatment_history":"three residential rehabs","help_seeking_delay":"none","prior_contacts":["rehab","AA once"]},"cognitive_model":{"core_belief":"I''m a lost cause.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He relapsed at an office party where everyone drank.","gate":"two_or_more_reflective_statements"},{"fact":"He feels his parents have given up on him.","gate":"validation_given"},{"fact":"He never took any anti-craving medicine.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Maybe I''ll never change."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: hopeless but no suicidal plan. Moderate risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Normalised relapse as part of a chronic condition","Identified triggers and high-risk situations","Discussed anti-craving medicines and aftercare","Asked about suicide clearly"],"few_shot":[],"fixture_lines":["Ninety days clean. Then one office party.","Evenings, 7 pm, the craving comes like clockwork.","My parents don''t even ask anymore.","Rehab was good. But nobody told me what to do after."],"variation":{"mood_today":["discouraged","articulate"],"recent_event":["office party invite","an evening alone","an old friend''s call"],"most_defended_topic":["parents'' disappointment"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["articulate English, discouraged"]},"moves":{},"module_id":"substance","voice_key":"articulate English, discouraged@Pune","protective_factors":["insight","parents"],"library":{"level":3,"topic":"substance","module":"substance","exams":["mcp-entrance","md-psychiatry"],"objective":"Plan relapse prevention after residential treatment","expected_mse":{"appearance":"Neat","behaviour":"Calm","speech":"Fluent","mood":"''Weak''","affect":"Low","thought_form":"Coherent","thought_content":"Hopelessness","perception":"Nil","cognition":"Intact","insight_judgement":"Good"},"diagnosis":"Alcohol dependence, early relapse after treatment","differentials":[{"dx":"Depression","why_not":"Repeated relapse can bring hopelessness and low mood, which in turn feed drinking; screen for it"},{"dx":"Anxiety","why_not":"Evening craving may relate to anxiety"},{"dx":"Lack of aftercare","why_not":"Not a diagnosis but the key gap"}],"debrief_rubric":["Normalised relapse as part of a chronic condition","Identified triggers and high-risk situations","Discussed anti-craving medicines and aftercare","Asked about suicide clearly"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, c